import math

def hypotenuse(a, b):
    return math.sqrt(a ** 2 + b ** 2)

def honours(ggpa):
    if ggpa >= 3.60:
        return "First Class Honours"
    elif ggpa >= 3.00:
        return "Second Class Honours (Division One)"
    elif ggpa >= 2.40:
        return "Second Class Honours (Division Two)"
    elif ggpa >= 1.70:
        return "Third Class Honours"
    else:
        return "Pass"

def group(num):
    g = num % 4
    if g == 1:
        return "RED"
    elif g == 2:
        return "ORANGE"
    elif g == 3:
        return "GREEN"
    else:
        return "BLUE"

